package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name string
		text string
		width int
		want []string
	}{
		{
			name: "simple wrap",
			text: "hello world",
			width: 10,
			want: []string{"hello", "world"},
		},
		{
			name: "no wrap needed",
			text: "hello world",
			width: 20,
			want: []string{"hello world"},
		},
		{
			name: "multiple lines",
			text: "one two three four five",
			width: 8,
			want: []string{"one two", "three four", "five"},
		},
		{
			name: "word longer than width",
			text: "superlong short",
			width: 5,
			want: []string{"superlong", "short"},
		},
		{
			name: "whitespace collapse",
			text: "  hello   world  ",
			width: 10,
			want: []string{"hello", "world"},
		},
		{
			name: "empty input",
			text: "",
			width: 5,
			want: nil,
		},
		{
			name: "whitespace only input",
			text: "   \t\n  ",
			width: 5,
			want: nil,
		},
		{
			name: "zero width",
			text: "hello",
			width: 0,
			want: nil,
		},
		{
			name: "negative width",
			text: "hello",
			width: -1,
			want: nil,
		},
		{
			name: "single word fits",
			text: "hello",
			width: 5,
			want: []string{"hello"},
		},
		{
			name: "single word too long",
			text: "hello",
			width: 3,
			want: []string{"hello"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && got == nil && tt.want == nil {
				return
			}
			if len(got) == 0 && tt.want == nil {
				t.Fatalf("got empty slice, want nil")
			}
			if !equal(got, tt.want) {
				t.Errorf("Wrap(%q, %d) = %v, want %v", tt.text, tt.width, got, tt.want)
			}
		})
	}
}

func equal(a, b []string) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

